        ('90010019-0001-4000-8000-000000000022', '90010000-0000-4000-8000-000000000019', '90010019-0000-4000-8000-000000000022', 'Section D', 5, 34, '34'),
        ('90010019-0001-4000-8000-000000000023', '90010000-0000-4000-8000-000000000019', '90010019-0000-4000-8000-000000000023', 'Section D', 5, 35, '35'),
        ('90010019-0001-4000-8000-000000000024', '90010000-0000-4000-8000-000000000019', '90010019-0000-4000-8000-000000000024', 'Section D', 5, 36, '36'),
        ('90010019-0001-4000-8000-000000000025', '90010000-0000-4000-8000-000000000019', '90010019-0000-4000-8000-000000000025', 'Section E', 4, 37, '37'),
        ('90010019-0001-4000-8000-000000000026', '90010000-0000-4000-8000-000000000019', '90010019-0000-4000-8000-000000000026', 'Section E', 4, 38, '38'),
