        ('90010024-0001-4000-8000-000000000016', '90010000-0000-4000-8000-000000000024', '90010024-0000-4000-8000-000000000016', 'Section B', 2, 22, '22'),
        ('90010024-0001-4000-8000-000000000017', '90010000-0000-4000-8000-000000000024', '90010024-0000-4000-8000-000000000017', 'Section B', 2, 23, '23'),
        ('90010024-0001-4000-8000-000000000018', '90010000-0000-4000-8000-000000000024', '90010024-0000-4000-8000-000000000018', 'Section B', 2, 24, '24'),
        ('90010024-0001-4000-8000-000000000019', '90010000-0000-4000-8000-000000000024', '90010024-0000-4000-8000-000000000019', 'Section B', 2, 25, '25'),
        ('90010024-0001-4000-8000-00000000001a', '90010000-0000-4000-8000-000000000024', '90010024-0000-4000-8000-00000000001a', 'Section B', 2, 26, '26'),
        ('90010024-0001-4000-8000-00000000001b', '90010000-0000-4000-8000-000000000024', '90010024-0000-4000-8000-00000000001b', 'Section C', 3, 27, '27'),
        ('90010024-0001-4000-8000-00000000001c', '90010000-0000-4000-8000-000000000024', '90010024-0000-4000-8000-00000000001c', 'Section C', 3, 28, '28'),
        ('90010024-0001-4000-8000-00000000001d', '90010000-0000-4000-8000-000000000024', '90010024-0000-4000-8000-00000000001d', 'Section C', 3, 29, '29'),
        ('90010024-0001-4000-8000-00000000001e', '90010000-0000-4000-8000-000000000024', '90010024-0000-4000-8000-00000000001e', 'Section C', 3, 30, '30'),
        ('90010024-0001-4000-8000-00000000001f', '90010000-0000-4000-8000-000000000024', '90010024-0000-4000-8000-00000000001f', 'Section C', 3, 31, '31'),
        ('90010024-0001-4000-8000-000000000020', '90010000-0000-4000-8000-000000000024', '90010024-0000-4000-8000-000000000020', 'Section C', 3, 32, '32'),
